"""Unit 11: Tagalog Basic Course, Semester I, Unit 3, Chapter 3, Lesson 1: Meals of the Day.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (Teacher Edition, December 2020).
Audio, pictures, partner and group work are left out; the book's answer keys are used where it prints them
(quantities in spoken lines are written in words), and the English notes are mine."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


# ------------------------------------------------------------------ 1 meals of the day
